local bit32 = bit32 or bit

local function __b64decode(data)
  if crypt then
    if crypt.base64decode then
      local ok, r = pcall(crypt.base64decode, data)
      if ok and type(r) == "string" then return r end
    end
    if crypt.base64 and crypt.base64.decode then
      local ok, r = pcall(crypt.base64.decode, data)
      if ok and type(r) == "string" then return r end
    end
  end
  if base64 and base64.decode then
    local ok, r = pcall(base64.decode, data)
    if ok and type(r) == "string" then return r end
  end
  if base64_decode then
    local ok, r = pcall(base64_decode, data)
    if ok and type(r) == "string" then return r end
  end
  local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  data = string.gsub(data, "[^" .. b .. "=]", "")
  return (data:gsub(".", function(x)
    if x == "=" then return "" end
    local r, f = "", (b:find(x) - 1)
    for i = 6, 1, -1 do
      r = r .. (f % 2^i - f % 2^(i - 1) > 0 and "1" or "0")
    end
    return r
  end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
    if #x ~= 8 then return "" end
    local c = 0
    for i = 1, 8 do
      c = c + (x:sub(i, i) == "1" and 2^(8 - i) or 0)
    end
    return string.char(c)
  end))
end

local function __xor(str, keyBytes)
  local n, kl = #str, #keyBytes
  local t = table.create(n)
  for i = 1, n do
    t[i] = string.char(bit32.bxor(str:byte(i), keyBytes[((i - 1) % kl) + 1]))
  end
  return table.concat(t)
end

